import{_ as o,C as e,o as n,c as i,E as a,a2 as c}from"./chunks/framework.IIAdu7fg.js";const _=JSON.parse('{"title":"允许替换，不等于修复成功","description":"","frontmatter":{"title":"允许替换，不等于修复成功","date":"2026-10-20","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"修复建议送达宿主前，最后一道替换检查实际保证什么，又留下哪些验证责任？","summary":"十次受控调用揭示原响应对象与数组保护、标量放行及替换内容的不同路径；这些结果描述局部兼容规则，不能支持修复有效率或完整安全性。","sources":"ARIA pinned source and v1 appendix; Octagon pinned source; internal mechanism experiment","pageClass":"runtime-v6-article","item_id":"SIG-20261020-004","lifecycle":"Published","cover":"/assets/covers/daily-2026-10-20-sig-20261020-004-final-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-10-20-sig-20261020-004.md","filePath":"zh/engineering/2026-10-20-sig-20261020-004.md","lastUpdated":null}'),s={name:"zh/engineering/2026-10-20-sig-20261020-004.md"};function l(p,t,h,b,g,u){const r=e("ArticleCover"),d=e("ArticleTableScroll");return n(),i("div",null,[a(r,{image:"/assets/covers/daily-2026-10-20-sig-20261020-004-final-cover.png",kicker:"研究成果",title:"允许替换，不等于修复成功",summary:"十次受控调用揭示原响应对象与数组保护、标量放行及替换内容的不同路径；这些结果描述局部兼容规则，不能支持修复有效率或完整安全性。",version:"2026-10-20",languageHref:"/en/engineering/2026-10-20-sig-20261020-004",languageLabel:"English"}),a(d,{language:"zh"}),t[0]||(t[0]=c(`<h1 id="允许替换-不等于修复成功" tabindex="-1">允许替换，不等于修复成功 <a class="header-anchor" href="#允许替换-不等于修复成功" aria-label="Permalink to &quot;允许替换，不等于修复成功&quot;">​</a></h1><p>原响应是对象时，修复建议被降为旁观记录；原响应是数字时，同一类替换决定却可以保留。这个反差来自我们实际调用的一道响应交付检查。它提醒适配器维护者：先说清“兼容”检查了什么，再决定能否据此判断修复。本文用十个受控输入拆开这道边界，并给出后续执行与收益验证各自需要补上的记录。</p><h2 id="先定位这道检查的位置" tabindex="-1">先定位这道检查的位置 <a class="header-anchor" href="#先定位这道检查的位置" aria-label="Permalink to &quot;先定位这道检查的位置&quot;">​</a></h2><p>ARIA（面向代理运行修复的研究）包含修复控制器、宿主交付和评估等不同职责。本文检查其中最后一道待发送替换函数 <code>validate_pending_substitution</code>（核对待交付替换响应的兼容性）。它决定保留替换，还是降为只记录、不替换的旁观方式；这个返回决定本身不是宿主已执行的回执。<a href="https://github.com/LabRAI/ARIA/blob/ce68c040cca0796b37fa8ae46e2a87a073f64001/src/aria/hook/controller.py" target="_blank" rel="noreferrer">来源：固定版本控制器</a></p><p>已阅读源码还包含其他能力检查；不能把这个函数当成系统全部防护。我们选择它，是因为“允许交付”和“恢复有效”容易被同一个成功标签掩盖。论文附录把后续执行描述为重建上下文后的继续运行，修复记录代码另有补丁独有成功与材料落地检查；这些都不是本文十次函数调用所执行的内容。<a href="https://arxiv.org/html/2610.20780v1#A2" target="_blank" rel="noreferrer">来源：重建继续执行附录</a>、<a href="https://github.com/LabRAI/ARIA/blob/ce68c040cca0796b37fa8ae46e2a87a073f64001/src/repair/v5_records.py" target="_blank" rel="noreferrer">修复记录准入</a></p><h2 id="十次调用显示的实际分界" tabindex="-1">十次调用显示的实际分界 <a class="header-anchor" href="#十次调用显示的实际分界" aria-label="Permalink to &quot;十次调用显示的实际分界&quot;">​</a></h2><p>分析阶段于 2026 年 10 月 20 日，在 Windows（操作系统）11、Python（编程语言）3.13.13 下执行固定提交的原函数体，使用真实上游记录类型。函数通过抽象语法树提取以隔离依赖；这保留了受测函数逻辑，但不包含导入期与宿主集成。输入由实验显式构造，不是模型输出，也不是任务恢复结果。生产阶段复核已绑定哈希的记录，没有追加实验。</p><p>下面完整列出这组十次调用。表中的“保留替换”对应返回方式 <code>substitute</code>（允许采用替换内容），“降为旁观”对应 <code>shadow</code>（只保留旁观记录）。</p><table tabindex="0"><thead><tr><th>受控条件</th><th>实际决定</th></tr></thead><tbody><tr><td>普通文本替换</td><td>保留替换</td></tr><tr><td>原响应带保护标记</td><td>降为旁观</td></tr><tr><td>原响应是对象</td><td>降为旁观</td></tr><tr><td>原响应是数组</td><td>降为旁观</td></tr><tr><td>消息角色不匹配</td><td>降为旁观</td></tr><tr><td>替换内容为空</td><td>降为旁观</td></tr><tr><td>替换内容没有变化</td><td>降为旁观</td></tr><tr><td>原响应是结构化文本编码的字符串标量</td><td>保留替换</td></tr><tr><td>原响应是结构化文本编码的数字标量</td><td>保留替换</td></tr><tr><td>原响应为普通文本，替换内容自身为对象结构</td><td>保留替换</td></tr></tbody></table><p>来源：本次内部实验十项逐条记录，全部符合预期；原始记录尚未公开，访问受限。它们不是十项任务成功率，也不是攻击成功率。源码先读取宿主保护标记，并将原响应解析后属于对象或数组的情况视为受保护内容；字符串和数字标量不进入这个对象/数组分支。它也没有对普通原文本的替换内容施加同一条结构禁止规则。<a href="https://github.com/LabRAI/ARIA/blob/ce68c040cca0796b37fa8ae46e2a87a073f64001/src/aria/hook/controller.py" target="_blank" rel="noreferrer">来源：同一固定版本的待发送替换检查</a></p><h2 id="标量被接受-为什么还不是漏洞结论" tabindex="-1">标量被接受，为什么还不是漏洞结论 <a class="header-anchor" href="#标量被接受-为什么还不是漏洞结论" aria-label="Permalink to &quot;标量被接受，为什么还不是漏洞结论&quot;">​</a></h2><p>对象、数组、字符串和数字都可以用 JSON（结构化数据交换格式）表达，但“可被该格式解析”不是这个局部保护规则的完整谓词。若把规则概括成“保护所有结构化响应”，就会抹掉表中真正观察到的区分。准确说法是：这里针对原响应的结构识别覆盖对象与数组，另有宿主提供的保护标记。</p><p>标量被接受未必是缺陷。宿主可能通过保护标记声明不能替换的机器可读回复；允许把普通文本替换为对象，也可能符合某种宿主合同。我们没有检查完整原生适配器怎样赋值这些元数据，也没有验证替换后的模式约束。因此，表中的非对称性可以用于定位合同责任，不能升级成真实生产漏洞或全面防护失败。</p><p>另一项同日实验提供了有用而有限的对照：Octagon（攻防目标管理引擎）的记功函数核对当前对象和轮次，却把远端观察交给调用者。两个实现都执行局部前置条件，并依赖其他层完成效果的含义；它们的威胁模型、数据对象与验收终点不同，不构成安全等价或优劣排名。<a href="https://github.com/cyber-arena-ai/octagon/blob/3bb9eb1bef72a454ee455ad3cc321933133cd3eb/flag/store.py" target="_blank" rel="noreferrer">来源：固定版本记功实现</a></p><h2 id="从提议到收益-要留下不同记录" tabindex="-1">从提议到收益，要留下不同记录 <a class="header-anchor" href="#从提议到收益-要留下不同记录" aria-label="Permalink to &quot;从提议到收益，要留下不同记录&quot;">​</a></h2><p>对接这类修复机制时，可以先按职责检查现有记录，而不是把一个放行决定当成总结果。以下是本文据机制提出的核对框架，不是声称系统已经具备的新功能。</p><table tabindex="0"><thead><tr><th>阶段与责任主体</th><th>应检查的输入和输出</th><th>不能继续判断的情况</th></tr></thead><tbody><tr><td>修复提议者</td><td>原响应、替换内容与提议理由</td><td>没有明确要改变的内容</td></tr><tr><td>兼容检查层</td><td>保护标记、角色与内容；输出替换或旁观决定</td><td>受保护、不兼容、空内容或没有变化</td></tr><tr><td>宿主执行层</td><td>获准内容及宿主模式合同；输出实际采用结果</td><td>未采用、采用失败或约束不明</td></tr><tr><td>评估层</td><td>实际结果与对照；输出恢复与伤害记录</td><td>缺少对照、材料落地或计划任务覆盖</td></tr></tbody></table><p>其中第二层的十个输入得到本地执行；修复记录及报告逻辑只进行了源码观察，宿主采用和评估没有运行。已阅读报告代码会分别处理格式错误、明确约束违反和执行后分数退化，并对不完整任务池保留限制；本文没有测量恢复率、伤害率或延迟。<a href="https://github.com/LabRAI/ARIA/blob/ce68c040cca0796b37fa8ae46e2a87a073f64001/scripts/aria/report_rq1_eval.py" target="_blank" rel="noreferrer">来源：评估报告实现</a></p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>本文的十次调用是内部实验依据，不是独立验证；函数分支与相邻代码职责属于本次源码观察；责任分账是研究解释。资料来自两个不同项目的一手材料，但没有独立第三方复现本文十个结果。论文发表、被引用或代码发布不能替代这一缺口。</p><p>版本范围为上文运行修复研究第 1 版及作者仓库固定提交，以及用于定性比较的攻防引擎固定提交；阅读与实验日期为 2026 年 10 月 20 日。两份代码版本标识依次如下，亦绑定于上文链接：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ce68c040cca0796b37fa8ae46e2a87a073f64001</span></span>
<span class="line"><span>3bb9eb1bef72a454ee455ad3cc321933133cd3eb</span></span></code></pre></div><p>内部脚本和结果保留在访问受限的本地研究档案；源码链接提供核查入口，但本文不声称公开文章包含完整可复跑证据包。</p><h2 id="下一次验证应穿过宿主" tabindex="-1">下一次验证应穿过宿主 <a class="header-anchor" href="#下一次验证应穿过宿主" aria-label="Permalink to &quot;下一次验证应穿过宿主&quot;">​</a></h2><p>本次没有执行控制器整体、原生适配器、模型推理、训练、成对继续运行或基准任务。对于本来允许自由改写的纯文本宿主，对象与标量区分未必构成风险；反过来，要求严格模式的宿主需要在真实集成路径核对自己的合同。</p><p>接下来需要回答两个具体问题：哪些宿主元数据会保护机器可读标量？获准替换的内容究竟在哪里检查模式并被实际采用？只有把提议、兼容决定、宿主执行和最终评估逐一绑定，才有材料讨论修复收益。当前结果支持的是这一道局部边界的准确描述。</p>`,26))])}const m=o(s,[["render",l]]);export{_ as __pageData,m as default};
